/*
 * Benchmark following ops on CH56x processor:
 *
 *   - unaligned memory access code generated by the compiler
 *   - number of cycles integer arithmetic operations(+, -, *, /, %)
 */

#define FREQ_SYS   80000000

#include "CH56x_common.h"
#include "CH56x_sys.h"
#include <string.h>

/* Just to get some data to work on */
__attribute__((__section__(".stack >RAM")))
static const uint8_t stack_addr[2048];

static void init_stdio_metal(void)
{
#if defined(DEBUG) && DEBUG >= 0
	static const struct ch56x_stdio_desc desc[3] = {
		{ },
		{115200, DEBUG, 1, 1},
		{115200, DEBUG, 1, 1}
	};

	ch56x_stdio_open(desc, FREQ_SYS);
#endif
}

__attribute__((interrupt("machine")))
void HardFault_Handler(void)
{
	fprintf(stderr,
			"\n\n========== fault ==========\n"
			"mepc:  %08" PRIx32 "\n"
			"cause: %08" PRIx32 "\n"
			"mtval: %08" PRIx32 "\n"
			"===========================\n",
			__get_MEPC(), __get_MCAUSE(), __get_MTVAL());

	fflush(stdout);
	fflush(stderr);
	mDelaymS(10);

	for(;;)
		LowPower_Halt_WFE();
}

static void start_ticker(void)
{
	/* The intermediate register */
	SysTick->CMP = UINT64_MAX;
	/*
	 * 8: Load the counter with the new value
	 * 1: use HCLK(SYSFREQ)
	 * 0: enable
	 */
	SysTick->CTLR = (1 << 8) | (1 << 2) | (1 << 0);
}

static uint64_t stop_ticker(void)
{
	SysTick->CTLR = 0;
	return UINT64_MAX - SysTick->CNT;
}

/*
 * If the alignment of data is known at compile time and the compiler optimises
 * for the target system which does not support unaligned memory access, the
 * compiler generates the code that involves byte-by-byte loads(see
 * -mstrict-align). At the time of writing this function(GCC version 16.1.0),
 * the compiler options to control this behaviour doesn't seem to have any
 * effect on static functions.
 *
 * This is due to a design error in the arch. RISC-V is not clear on how fast
 * unaligned memory access should be handled.
 *
 * To work around this issue, this function is made always_inline to force the
 * compiler to generate two variants of the function for testing aligned and
 * unaligned access.
 *
 * If the numbers come out the same, it means that this hack didn't work and the
 * compiler generated the same code for both call points. Please report the bug
 * if that's the case.
 */
__attribute__((always_inline))
static inline void do_access(const char *msg, volatile void *addr)
{
	volatile long *n = addr;
	const long *p = (const long *)stack_addr;
	const size_t cnt = sizeof(stack_addr) / sizeof(n);
	uint64_t tick;

	printf("%scnt %20u\n", msg, cnt);

	start_ticker();
	for (size_t i = 0; i < cnt; i++)
		*n += p[i];
	tick = stop_ticker();
	printf("%sadd %20" PRIuMAX "\n", msg, tick);

	start_ticker();
	for (size_t i = 0; i < cnt; i++)
		*n -= p[i];
	tick = stop_ticker();
	printf("%ssub %20" PRIuMAX "\n", msg, tick);

	start_ticker();
	for (size_t i = 0; i < cnt; i++)
		*n *= p[i];
	tick = stop_ticker();
	printf("%smul %20" PRIuMAX "\n", msg, tick);

	/* (no division by zero trap on RISC-V) */

	start_ticker();
	for (size_t i = 0; i < cnt; i++)
		*n /= p[i];
	tick = stop_ticker();
	printf("%sdiv %20" PRIuMAX "\n", msg, tick);

	start_ticker();
	for (size_t i = 0; i < cnt; i++)
		*n %= p[i];
	tick = stop_ticker();
	printf("%smod %20" PRIuMAX "\n", msg, tick);
}

int main(void)
{
	volatile uint8_t buf[sizeof(long) + 1] = {0,};

	SystemInit(FREQ_SYS);
	Delay_Init(FREQ_SYS);
	init_stdio_metal();

	/*
	 * THE MACHINE KNOWS!
	 *
	 * The compiler knows that the following addresses are aligned and
	 * unaligned, respectively, and generate a variant for each.
	 */

	do_access("Aligned access:   ", buf);
	do_access("Unaligned access: ", buf + 1);

	fflush(stdout);
	fflush(stderr);
	mDelaymS(10);

	for(;;)
		LowPower_Halt_WFE();
}
